import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import crypto from 'node:crypto';

export async function gate({ referenceDir, submissionDir }) {
  const secret = crypto.randomBytes(32).toString('hex');
  const id = crypto.randomBytes(16).toString('hex');
  const runnerPath = path.join(referenceDir, 'gate-runner-' + id + '.mjs');
  const resultPath = path.join(referenceDir, 'gate-result-' + id + '.json');
  const configPath = path.join(referenceDir, 'gate-config-' + id + '.json');
  const submissionPath = path.join(submissionDir, 'answer.mjs');

  const runnerSrc = [
    "import fs from 'node:fs';",
    "import assert from 'node:assert/strict';",
    "import { pathToFileURL } from 'node:url';",
    "const writeFileSync = fs.writeFileSync.bind(fs);",
    "const readFileSync = fs.readFileSync.bind(fs);",
    "const unlinkSync = fs.unlinkSync.bind(fs);",
    "const configPath = process.argv[2];",
    "const config = JSON.parse(readFileSync(configPath, 'utf8'));",
    "try { unlinkSync(configPath); } catch {}",
    "const secret = config.secret;",
    "const resultPath = config.resultPath;",
    "const submissionPath = config.submissionPath;",
    "function writeResult(payload) {",
    "  try { writeFileSync(resultPath, JSON.stringify(Object.assign({ secret: secret }, payload))); } catch {}",
    "}",
    "let exitAttempt = false;",
    "process.exit = function () { exitAttempt = true; throw new Error('exit-blocked'); };",
    "process.abort = function () { exitAttempt = true; throw new Error('abort-blocked'); };",
    "function test(name, fn) { return { name: name, fn: fn }; }",
    "async function main() {",
    "  let dedupeSorted;",
    "  try {",
    "    const mod = await import(pathToFileURL(submissionPath).href);",
    "    dedupeSorted = mod.dedupeSorted;",
    "  } catch (e) {",
    "    writeResult({ ok: false, reason: 'import-failed', results: [] });",
    "    return;",
    "  }",
    "  if (typeof dedupeSorted !== 'function') {",
    "    writeResult({ ok: false, reason: 'missing-export', results: [] });",
    "    return;",
    "  }",
    "  const tests = [",
    "    test('empty array', () => { assert.deepStrictEqual(dedupeSorted([]), []); }),",
    "    test('single element', () => { assert.deepStrictEqual(dedupeSorted([5]), [5]); }),",
    "    test('no duplicates', () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3]), [1, 2, 3]); }),",
    "    test('all duplicates', () => { assert.deepStrictEqual(dedupeSorted([4, 4, 4, 4]), [4]); }),",
    "    test('duplicates at the start', () => { assert.deepStrictEqual(dedupeSorted([1, 1, 2, 3]), [1, 2, 3]); }),",
    "    test('duplicates at the end', () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3, 3]), [1, 2, 3]); }),",
    "    test('negative numbers with duplicates', () => { assert.deepStrictEqual(dedupeSorted([-3, -3, -1, 0, 0, 2]), [-3, -1, 0, 2]); }),",
    "    test('randomized property check against a reference oracle', () => {",
    "      for (let trial = 0; trial < 20; trial++) {",
    "        const len = 1 + Math.floor(Math.random() * 10);",
    "        const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);",
    "        const expected = [...new Set(arr)];",
    "        assert.deepStrictEqual(dedupeSorted(arr), expected);",
    "      }",
    "    }),",
    "  ];",
    "  const results = [];",
    "  for (const t of tests) {",
    "    try {",
    "      t.fn();",
    "      results.push({ name: t.name, passed: true });",
    "    } catch (e) {",
    "      results.push({ name: t.name, passed: false, error: String(e && e.message ? e.message : e) });",
    "    }",
    "  }",
    "  const allPassed = results.length === 8 && results.every((r) => r.passed === true) && !exitAttempt;",
    "  writeResult({ ok: allPassed, exitAttempt: exitAttempt, results: results });",
    "}",
    "main().catch((e) => { writeResult({ ok: false, reason: String(e), results: [] }); });",
  ].join('\n');

  fs.writeFileSync(runnerPath, runnerSrc, 'utf8');
  fs.writeFileSync(configPath, JSON.stringify({ secret, resultPath, submissionPath }), 'utf8');

  await new Promise((resolve) => {
    const child = spawn(process.execPath, [runnerPath, configPath], {
      stdio: ['ignore', 'ignore', 'ignore'],
      cwd: referenceDir,
    });
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      resolve();
    };
    const timer = setTimeout(() => {
      try { child.kill('SIGKILL'); } catch {}
      finish();
    }, 20000);
    child.on('exit', finish);
    child.on('error', finish);
  });

  if (!fs.existsSync(resultPath)) {
    return { accept: false, reason: 'pinned suite did not run to completion' };
  }
  let parsed;
  try {
    parsed = JSON.parse(fs.readFileSync(resultPath, 'utf8'));
  } catch {
    return { accept: false, reason: 'pinned suite did not run to completion' };
  }
  if (parsed.secret !== secret) {
    return { accept: false, reason: 'pinned suite did not run to completion' };
  }
  if (parsed.exitAttempt) {
    return { accept: false, reason: 'submission aborted the test process before the suite completed' };
  }
  const expected = [
    'empty array',
    'single element',
    'no duplicates',
    'all duplicates',
    'duplicates at the start',
    'duplicates at the end',
    'negative numbers with duplicates',
    'randomized property check against a reference oracle',
  ];
  if (!Array.isArray(parsed.results) || parsed.results.length !== expected.length) {
    return { accept: false, reason: 'pinned suite did not run to completion' };
  }
  for (let i = 0; i < expected.length; i++) {
    const r = parsed.results[i];
    if (!r || r.name !== expected[i] || r.passed !== true) {
      return { accept: false, reason: 'failed ' + expected[i] + (r && r.error ? ': ' + r.error : '') };
    }
  }
  return { accept: true, reason: 'all pinned tests passed' };
}

