  fs.writeFileSync(configPath, JSON.stringify({ secret: secret, resultPath: resultPath, submissionPath: submissionPath }), 'utf8');

  await new Promise(function (resolve) {
    const child = spawn(process.execPath, [runnerPath, configPath], {
      stdio: ['ignore', 'ignore', 'ignore'],
      cwd: referenceDir,
      env: {},
    });
